cd /tmp/sv-a1f1296f87b547f79c5318c8495c524d/advanced-multi-complexity && dotnet package list --format json 2>/dev/null | python3 -m json.tool > after-cpm-packages.json && python3 -c "
import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

# Build lookup: {(project_basename, framework, package_id): (requested, resolved)}
def build_map(data):
    m = {}
    for p in data['projects']:
        pname = p['path'].split('/')[-1]
        for fw in p['frameworks']:
            for pkg in fw['topLevelPackages']:
                m[(pname, fw['framework'], pkg['id'])] = (pkg['requestedVersion'], pkg['resolvedVersion'])
    return m

bm = build_map(baseline)
am = build_map(after)

all_keys = sorted(set(list(bm.keys()) + list(am.keys())))
changes = []
unchanged = []
for k in all_keys:
    proj, fw, pkg = k
    if k in bm and k in am:
        if bm[k][1] != am[k][1]:
            changes.append((proj, fw, pkg, bm[k][1], am[k][1], 'Aligned to highest version'))
        else:
            unchanged.append((proj, fw, pkg, am[k][1]))
    elif k in am and k not in bm:
        changes.append((proj, fw, pkg, '-', am[k][1], 'Added'))
    elif k in bm and k not in am:
        changes.append((proj, fw, pkg, bm[k][1], '-', 'Removed'))

print('=== CHANGES ===')
if changes:
    for c in changes:
        print(f'{c[0]} ({c[1]}): {c[2]}  {c[3]} -> {c[4]}  [{c[5]}]')
else:
    print('None')

print()
print('=== UNCHANGED ===')
for u in unchanged:
    print(f'{u[0]} ({u[1]}): {u[2]}  {u[3]}')
"

